{"path": "/tmp/sv-78a87946a1464d7aa07404c0f795af43/RecipeShare/Services/RecipeService.cs", "file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes over the dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra cheese."
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or pan-sear the chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice."
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nCarrots\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar\nChili flakes",
            Steps = "1. Soak rice noodles in warm water 20 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: tamarind paste, fish sauce, sugar, chili.\n4. Stir-fry carrots and green onions.\n5. Add noodles and sauce, toss to combine.\n6. Top with bean sprouts, peanuts, and lime."
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef over medium-high heat.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry skillet.\n4. Fill tortillas with seasoned beef.\n5. Top with lettuce, tomato, cheese, sour cream, and salsa."
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
            Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix everything together with lime juice and salt.\n5. Serve immediately with tortilla chips."
        },
        new Recipe
        {
            Id = 7, Title = "Tom Yum Soup", Category = "Thai",
            Ingredients = "Shrimp\nLemongrass\nGalangal\nKaffir lime leaves\nChili paste\nFish sauce\nLime juice\nMushrooms\nCilantro",
            Steps = "1. Bring water to a boil with lemongrass, galangal, and lime leaves.\n2. Add mushrooms and chili paste.\n3. Add shrimp and cook until pink.\n4. Season with fish sauce and lime juice.\n5. Garnish with cilantro and serve hot."
        },
        new Recipe
        {
            Id = 8, Title = "Palak Paneer", Category = "Indian",
            Ingredients = "Spinach\nPaneer\nOnion\nTomatoes\nGarlic\nGinger\nGreen chili\nCumin\nGaram masala\nCream",
            Steps = "1. Blanch spinach and blend to a puree.\n2. Cube paneer and lightly fry until golden.\n3. Sauté onion, garlic, ginger, and green chili.\n4. Add tomatoes and cook until soft.\n5. Add spinach puree and spices, simmer 10 minutes.\n6. Add paneer cubes and cream. Serve with naan."
        },
    };

    private int _nextId;

    public RecipeService()
    {
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}
"}

