arguments.file_text:
@page "/category/{CategoryName}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes is null || recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>⭐ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Home</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe>? recipes;

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

    <h3 class="mt-4">🧾 Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>📋 Steps</h3>
    <div class="card">
        <div class="card-body">
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <a href="category/@recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@inject RecipeShare.Services.RecipeService RecipeService

<div class="my-3">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                disabled="@hasRated"
                title="@star star(s)">
            @(star <= displayStars ? "★" : "☆")
        </button>
    }

    @if (hasRated)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }

    @if (averageRating > 0)
    {
        <div class="text-muted small mt-1">
            Average: @averageRating.ToString("0.0") / 5 (@ratingCount ratings)
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int displayStars;
    private bool hasRated;
    private double averageRating;
    private int ratingCount;

    protected override void OnParametersSet()
    {
        LoadRating();
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        displayStars = stars;
        hasRated = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            ratingCount = recipe.RatingCount;
        }
    }
}

